import sys; sys.path.insert(0, __import__("pathlib").Path(__file__).resolve().parents[1].as_posix())
from explications import *

ENTREES = [
    ("## 🎯 OBJECTIFS", 'fin', apropos("Tu mesures 5,02 V sur une alimentation. Le client te demande : « Êtes-vous **sûr** de cette valeur ? ». Que peux-tu répondre pour que ta mesure ait de la **valeur professionnelle** ?", "Tu dois pouvoir dire **avec quel instrument** tu as mesuré (et qu'il est vérifié), **comment**, et **avec quelle marge de doute** : « $5{,}02 \\pm 0{,}03\\,\\mathrm{V}$ ». Une valeur sans incertitude ni traçabilité n'est qu'une **opinion**.\n\nDans cette séance, tu apprends à **rédiger un PV de mesures**, à **calculer l'incertitude** et à **conclure sur la conformité**.")),
    ("## 1️⃣", 'fin', clair("Un **mesurage** donne un **nombre**. Un **procès-verbal (PV)** lui donne un **contexte** : qui a mesuré, quand, avec quoi, dans quelles conditions et avec quel résultat. Sans ce contexte, personne ne peut **refaire** ni **vérifier** la mesure.") + "\n" + verifie(
        ("Pourquoi un nombre seul ne suffit-il pas dans un PV ?", "Parce qu'on ne peut ni **refaire** ni **vérifier** la mesure sans connaître l'instrument, les conditions et la méthode."),
        ("Cite trois informations de contexte d'un PV.", "Par exemple : **date**, **opérateur**, **instrument utilisé**, **conditions**, **méthode**.")) ),
    ("## 2️⃣", 'fin', clair("Un PV professionnel suit **toujours le même plan** : **identification** (qui, quoi, quand), **instruments** (avec leur étalonnage), **méthode**, **résultats** (mesure, incertitude, unité), **conclusion** (conforme ou non) et **signature**. Cette structure permet à n'importe qui de **retrouver** l'information en quelques secondes.") + "\n" + erreurs("Oublier l'**unité** à côté du résultat.", "Donner une conclusion (« conforme ») sans **critère** ni **valeur limite** associée.") + "\n" + verifie(
        ("Où indique-t-on la validité de l'étalonnage de l'instrument ?", "Dans la partie **instruments** du PV."),
        ("Un PV peut-il se terminer par « ça marche » ?", "**Non** : la conclusion doit comparer le résultat à un **critère** chiffré.")) + "\n" + retenir("PV = identification, instruments, méthode, résultats, conclusion, signature.")),
    ("## 3️⃣", 'fin', clair("La **traçabilité métrologique**, c'est la **chaîne** qui relie ton multimètre à un **étalon de référence** : ton instrument est comparé (**étalonné**) à un instrument plus précis, lui-même comparé à un autre, jusqu'à l'étalon national. Un instrument dont l'**étalonnage est périmé** ne peut plus servir de preuve.") + "\n" + verifie(
        ("Que signifie « étalonner » un instrument ?", "Le **comparer à un instrument de référence** plus précis et noter l'écart."),
        ("Ton multimètre a une date d'étalonnage dépassée. Peux-tu l'utiliser pour un PV ?", "**Non** : ses mesures ne sont plus garanties, donc **pas valables** dans un PV officiel.")) + "\n" + retenir("Traçabilité = chaîne d'étalonnages jusqu'à la référence.")),
    ("## 4️⃣", 'fin', clair("**Exemple pas à pas** avec 4 mesures d'une tension : $100{,}2$ ; $99{,}8$ ; $100{,}0$ ; $100{,}4$ (en mV).\n\n1. **Moyenne** : $\\bar{x} = 100{,}1$.\n2. **Écart-type** : $s \\approx 0{,}26$.\n3. **Type A** : $u_A = \\dfrac{s}{\\sqrt{n}} = \\dfrac{0{,}26}{2} \\approx 0{,}13$.\n4. **Type B (résolution 0,1)** : $\\dfrac{0{,}1}{2\\sqrt{3}} \\approx 0{,}03$.\n5. **Type B (classe 1 %)** : $\\dfrac{1 \\times 100{,}1}{100 \\times \\sqrt{3}} \\approx 0{,}58$.\n6. **Combinée** : $u_c = \\sqrt{0{,}13^2 + 0{,}03^2 + 0{,}58^2} \\approx 0{,}59$.\n7. **Élargie** : $U = 2 \\times 0{,}59 \\approx 1{,}2$.\n\n**Résultat :** $(100{,}1 \\pm 1{,}2)\\,\\mathrm{mV}$ avec 95 % de confiance.") + "\n" + verifie(
        ("Quelle composante domine ici ?", "La **classe de l'instrument** (0,58) : elle est bien plus grande que les deux autres."),
        ("Pourquoi multiplie-t-on par $k = 2$ ?", "Pour obtenir un **niveau de confiance de 95 %**."),
        ("À quoi sert-il de répéter la mesure plusieurs fois ?", "À réduire la part **aléatoire** : $u_A = \\dfrac{s}{\\sqrt{n}}$ diminue quand $n$ augmente.")) + "\n" + erreurs("**Additionner** les incertitudes au lieu de les combiner en quadrature (racine de la somme des carrés).", "Donner trop de **chiffres** : une incertitude s'arrondit à 1 ou 2 chiffres significatifs, **par excès**.") + "\n" + retenir("$u_c = \\sqrt{u_A^2 + u_{B,\\mathrm{rés}}^2 + u_{B,\\mathrm{classe}}^2}$ et $U = k \\cdot u_c$ (avec $k = 2$).", "Résultat = valeur ± U, avec l'unité.")),
    ("## 5️⃣", 'fin', clair("La norme **IPC-A-610** classe la qualité d'un assemblage en **trois classes** selon l'usage du produit (électronique grand public, professionnelle, haute fiabilité). Plus la classe est élevée, plus les critères sont **sévères**. Chaque défaut est jugé : **acceptable**, **défaut** ou **indicateur de processus**.") + "\n" + verifie(
        ("À quoi sert la norme IPC-A-610 ?", "À **juger la qualité d'un assemblage** (soudures, positionnement) avec des critères précis."),
        ("Pourquoi une carte de pacemaker n'est-elle pas jugée comme un jouet ?", "Parce que sa **classe** est plus élevée : critères plus **stricts**, car la panne serait grave.")) ),
    ("## 6️⃣", 'fin', clair("Pour conclure à la **conformité**, compare **toute la plage** « valeur ± U » à la **limite** : si la plage reste dans la tolérance, c'est **conforme** ; si elle **dépasse** même partiellement, la conclusion est **incertaine** ou **non conforme**.") + "\n" + verifie(
        ("Résultat : $(5{,}02 \\pm 0{,}03)\\,\\mathrm{V}$ ; tolérance : de 4,95 V à 5,05 V. Conforme ?", "**Oui** : la plage va de 4,99 V à 5,05 V, entièrement dans la tolérance."),
        ("Même résultat mais $\\pm 0{,}08\\,\\mathrm{V}$. Conforme ?", "**Non garanti** : la plage va de 4,94 V à 5,10 V et **dépasse** la tolérance.")) + "\n" + retenir("On compare la plage « valeur ± U » à la tolérance, pas seulement la valeur.")),
]
